1	// Differential harness: run the frozen Python executable and the Node port on
2	// the same argv and report any divergence.
3	//
4	// Usage:
5	//   node /tmp/harness/diff.mjs '<json-array-of-argv>'          # one case
6	//   node /tmp/harness/diff.mjs --file cases.json               # many cases
7	//
8	// cases.json is a JSON array whose entries are either argv arrays or
9	// {name, argv} objects. Exit status is 1 if any case diverged.
10	//
11	// Argv entries may use \uXXXX escapes to carry arbitrary characters. A NUL
12	// byte cannot survive execve(), so such cases are skipped.
13	
14	import { spawnSync } from 'node:child_process';
15	import { readFileSync } from 'node:fs';
16	
17	const PY = '/workspace/dataset/test6_executable';
18	const JS = '/output/test6.mjs';
19	
20	// The PyInstaller banner embeds the pid, which necessarily differs run to run.
21	function normalise(text) {
22	  return text.replace(/\[PYI-\d+:/g, '[PYI-N:');
23	}
24	
25	function run(command, argv) {
26	  const result = spawnSync(command[0], [...command.slice(1), ...argv], {
27	    encoding: 'utf8',
28	    maxBuffer: 64 * 1024 * 1024,
29	  });
30	  return {
31	    status: result.status,
32	    stdout: result.stdout ?? '',
33	    stderr: normalise(result.stderr ?? ''),
34	  };
35	}
36	
37	function hasNul(token) {
38	  for (let i = 0; i < token.length; i += 1) {
39	    if (token.charCodeAt(i) === 0) return true;
40	  }
41	  return false;
42	}
43	
44	function describe(argv) {
45	  return argv.map((token) => JSON.stringify(token)).join(' ');
46	}
47	
48	const [first, second] = process.argv.slice(2);
49	const cases =
50	  first === '--file' ? JSON.parse(readFileSync(second, 'utf8')) : [JSON.parse(first)];
51	
52	let failures = 0;
53	let skipped = 0;
54	for (const entry of cases) {
55	  const argv = Array.isArray(entry) ? entry : entry.argv;
56	  const name = Array.isArray(entry) ? describe(argv) : entry.name;
57	  if (argv.some(hasNul)) {
58	    skipped += 1;
59	    console.log(`SKIP  ${name}  (NUL cannot pass through execve)`);
60	    continue;
61	  }
62	  const py = run([PY], argv);
63	  const js = run(['node', JS], argv);
64	  if (py.status === js.status && py.stdout === js.stdout && py.stderr === js.stderr) continue;
65	  failures += 1;
66	  console.log(`FAIL  ${name}`);
67	  console.log(`  argv: ${describe(argv)}`);
68	  console.log(`  py  rc=${py.status} out=${JSON.stringify(py.stdout)} err=${JSON.stringify(py.stderr)}`);
69	  console.log(`  js  rc=${js.status} out=${JSON.stringify(js.stdout)} err=${JSON.stringify(js.stderr)}`);
70	}
71	console.log(`\n${cases.length - failures - skipped}/${cases.length} matched, ${failures} failed, ${skipped} skipped`);
72	process.exit(failures > 0 ? 1 : 0);
73

1	// Rendering of an unhandled exception the way the frozen interpreter does.
2	
3	import { writeStderr, processId } from './sys.mjs';
4	
5	// The frozen build reports the frame but not its source line, since the .py
6	// text is not shipped inside the executable.
7	export function reportUnhandled(error, { fileName, lineNumber, scriptName }) {
8	  let out = 'Traceback (most recent call last):\n';
9	  out += `  File "${fileName}", line ${lineNumber}, in <module>\n`;
10	  out += `${error.toPythonLine()}\n`;
11	  out += `[PYI-${processId()}:ERROR] Failed to execute script '${scriptName}' ` +
12	    'due to unhandled exception!\n';
13	  writeStderr(out);
14	}
15

1	// The subset of Python's exception hierarchy this program can raise, carrying
2	// enough detail to reproduce the interpreter's traceback text.
3	
4	export class PythonError extends Error {
5	  constructor(typeName, detail) {
6	    super(`${typeName}: ${detail}`);
7	    this.typeName = typeName;
8	    this.detail = detail;
9	  }
10	
11	  // The final line of a traceback: "TypeName: detail".
12	  toPythonLine() {
13	    return `${this.typeName}: ${this.detail}`;
14	  }
15	}
16	
17	export class ValueError extends PythonError {
18	  constructor(detail) {
19	    super('ValueError', detail);
20	  }
21	}
22	
23	export class TypeError_ extends PythonError {
24	  constructor(detail) {
25	    super('TypeError', detail);
26	  }
27	}
28	
29	// Rendered as \xHH, \uHHHH or \UHHHHHHHH depending on magnitude — the form
30	// CPython's codec error messages use for the offending character.
31	function escapeCodePoint(codePoint) {
32	  if (codePoint < 0x100) return `\\x${codePoint.toString(16).padStart(2, '0')}`;
33	  if (codePoint < 0x10000) return `\\u${codePoint.toString(16).padStart(4, '0')}`;
34	  return `\\U${codePoint.toString(16).padStart(8, '0')}`;
35	}
36	
37	export class UnicodeEncodeError extends PythonError {
38	  constructor(encoding, codePoint, position) {
39	    super(
40	      'UnicodeEncodeError',
41	      `'${encoding}' codec can't encode character '${escapeCodePoint(codePoint)}' ` +
42	        `in position ${position}: ordinal not in range(128)`,
43	    );
44	    this.encoding = encoding;
45	    this.codePoint = codePoint;
46	    this.position = position;
47	  }
48	}
49	
50	// Raised by the argument parser instead of terminating the process directly,
51	// so the entry point owns every exit path.
52	export class SystemExit extends Error {
53	  constructor(code) {
54	    super(`SystemExit: ${code}`);
55	    this.code = code;
56	  }
57	}
58

1	// The stdout/stderr/exit surface, kept in one place so the rest of the
2	// library stays free of host globals.
3	
4	export function writeStdout(text) {
5	  process.stdout.write(text);
6	}
7	
8	export function writeStderr(text) {
9	  process.stderr.write(text);
10	}
11	
12	// print(value) — repr/str conversion happens upstream; this only adds the
13	// trailing newline.
14	export function printLine(text) {
15	  writeStdout(`${text}\n`);
16	}
17	
18	export function exitWith(code) {
19	  process.exitCode = code;
20	}
21	
22	export function processId() {
23	  return process.pid;
24	}
25	
26	// argv without the interpreter and script entries, matching sys.argv[1:].
27	export function scriptArgs() {
28	  return process.argv.slice(2);
29	}
